import sys
from collections import defaultdict

MOD = 12345

def solve(n, c, conditions):
    from functools import lru_cache

    @lru_cache(None)
    def dp(remaining, state):
        if remaining == 0:
            return 1
        total_ways = 0
        for crime, mult in state.items():
            if (remaining - mult) >= 0:
                new_state = state.copy()
                new_state[crime] += mult
                total_ways = (total_ways + dp(remaining - mult, tuple(sorted(new_state.items())))) % MOD
        return total_ways

    crime_conditions = defaultdict(list)
    for crime, mult in conditions:
        crime_conditions[crime].append(mult)

    initial_state = {crime: min(mults) for crime, mults in crime_conditions.items()}

    return dp(n, tuple(sorted(initial_state.items())))

def main():
    import sys
    input = sys.stdin.read().split()
    index = 0
    n = int(input[index])
    c = int(input[index + 1])
    index += 2
    conditions = []
    for _ in range(c):
        crime = input[index]
        mult = int(input[index + 1])
        conditions.append((crime, mult))
        index += 2
    result = solve(n, c, conditions)
    print(result)

if __name__ == "__main__":
    main()
